/** Connect is the only RPC. Pi initiates one long-lived stream per runtime. */
export type IntegrationService = typeof IntegrationService;
export const IntegrationService = {
  connect: {
    path: "/phi.pi.v1.Integration/Connect" as const,
    requestStream: true as const,
    responseStream: true as const,
    requestSerialize: (value: PiToPhi): Buffer => Buffer.from(PiToPhi.encode(value).finish()),
    requestDeserialize: (value: Buffer): PiToPhi => PiToPhi.decode(value),
    responseSerialize: (value: PhiToPi): Buffer => Buffer.from(PhiToPi.encode(value).finish()),
    responseDeserialize: (value: Buffer): PhiToPi => PhiToPi.decode(value),
  },
} as const;

export interface IntegrationServer extends UntypedServiceImplementation {
  connect: handleBidiStreamingCall<PiToPhi, PhiToPi>;
}

export interface IntegrationClient extends Client {
  connect(): ClientDuplexStream<PiToPhi, PhiToPi>;
  connect(options: Partial<CallOptions>): ClientDuplexStream<PiToPhi, PhiToPi>;
  connect(metadata: Metadata, options?: Partial<CallOptions>): ClientDuplexStream<PiToPhi, PhiToPi>;
}

export const IntegrationClient = makeGenericClientConstructor(
  IntegrationService,
  "phi.pi.v1.Integration",
) as unknown as {
  new (address: string, credentials: ChannelCredentials, options?: Partial<ClientOptions>): IntegrationClient;
  service: typeof IntegrationService;
  serviceName: string;
};

type Builtin = Date | Function | Uint8Array | string | number | boolean | bigint | undefined;

export type DeepPartial<T> = T extends bigint ? string | number | bigint
  : T extends Builtin ? T : T extends globalThis.Array<infer U> ? globalThis.Array<DeepPartial<U>>
  : T extends ReadonlyArray<infer U> ? ReadonlyArray<DeepPartial<U>>
  : T extends { $case: string; value: unknown } ? { $case: T["$case"]; value?: DeepPartial<T["value"]> }
  : T extends {} ? { [K in keyof T]?: DeepPartial<T[K]> }
  : Partial<T>;

type KeysOfUnion<T> = T extends T ? keyof T : never;
export type Exact<P, I extends P> = P extends Builtin ? P
  : P & { [K in keyof P]: Exact<P[K], I[K]> } & { [K in Exclude<keyof I, KeysOfUnion<P>>]: never };

export interface MessageFns<T> {
  encode(message: T, writer?: BinaryWriter): BinaryWriter;
  decode(input: BinaryReader | Uint8Array, length?: number): T;
  create<I extends Exact<DeepPartial<T>, I>>(base?: I): T;
  fromPartial<I extends Exact<DeepPartial<T>, I>>(object: I): T;
}
